window.VO = [{"text": "Four friends are stuck on the wrong side of a canyon, at night.", "cap": "4 friends \u00b7 1 bridge \u00b7 night", "dur": 3.029, "extra": 0.4, "file": "vo/00.wav"}, {"text": "The old bridge holds only two people at a time, and they have just one torch.", "cap": "Max 2 at a time \u00b7 1 torch", "dur": 4.234, "extra": 0.5, "file": "vo/01.wav"}, {"text": "No one can cross without the torch, so someone has to carry it back each time.", "cap": "The torch must come back", "dur": 4.144, "extra": 0.5, "file": "vo/02.wav"}, {"text": "They cross at different speeds: one, two, five, and ten minutes. A pair moves at the slower person's pace.", "cap": "1 \u00b7 2 \u00b7 5 \u00b7 10 minutes", "dur": 6.154, "extra": 0.6, "file": "vo/03.wav"}, {"text": "In seventeen minutes, the bridge collapses. Can they all make it?", "cap": "17 minutes. Go!", "dur": 3.267, "extra": 0.4, "file": "vo/04.wav"}, {"text": "Pause, and comment your plan!", "cap": "Comment your plan!", "dur": 1.495, "extra": 9.6, "file": "vo/05.wav"}, {"text": "Most people let the fastest friend walk everyone across, one by one.", "cap": "The obvious plan...", "dur": 3.794, "extra": 0.4, "file": "vo/06.wav"}, {"text": "Ten, plus one, plus five, plus one, plus two. That's nineteen minutes. Too slow!", "cap": "10+1+5+1+2 = 19 \u2717", "dur": 4.738, "extra": 0.8, "file": "vo/07.wav"}, {"text": "The trick: send the two slowest across together, so their times overlap.", "cap": "Slowest two cross together", "dur": 3.76, "extra": 0.6, "file": "vo/08.wav"}, {"text": "First, one and two cross. Two minutes.", "cap": "1 & 2 cross \u00b7 2 min", "dur": 1.983, "extra": 0.6, "file": "vo/09.wav"}, {"text": "One brings the torch back. Three minutes.", "cap": "1 returns \u00b7 3 min", "dur": 2.185, "extra": 0.6, "file": "vo/10.wav"}, {"text": "Now five and ten cross together. Thirteen minutes.", "cap": "5 & 10 cross \u00b7 13 min", "dur": 2.819, "extra": 0.8, "file": "vo/11.wav"}, {"text": "Two brings the torch back. Fifteen minutes.", "cap": "2 returns \u00b7 15 min", "dur": 2.266, "extra": 0.6, "file": "vo/12.wav"}, {"text": "And one and two cross again. Seventeen minutes, exactly!", "cap": "1 & 2 cross \u00b7 17 min \u2713", "dur": 2.826, "extra": 0.6, "file": "vo/13.wav"}, {"text": "Everyone's safe, just as the bridge falls.", "cap": "Everyone's safe!", "dur": 2.32, "extra": 1.6, "file": "vo/14.wav"}, {"text": "Did you get seventeen? Follow for more puzzles!", "cap": "Follow for more puzzles", "dur": 2.611, "extra": 1.6, "file": "vo/15.wav"}];
